import json

grid = [list(map(int, row.split())) for row in grid_text.strip().split('\n')]
h, w = len(grid), len(grid[0])

# Pattern: 1s-only rows->1s, 6s-only rows->6s, others->8s
output_grid = []
for r in range(h):
    non8_vals = [v for v in grid[r] if v != 8]
    if not non8_vals:
        output_grid.append([8] * w)
    elif all(v == 1 for v in non8_vals):
        output_grid.append([1] * w)
    elif all(v == 6 for v in non8_vals):
        output_grid.append([6] * w)
    else:
        output_grid.append([8] * w)

print(json.dumps(output_grid))

grid = [list(map(int, row.split())) for row in grid_text.strip().split('\n')]
