import json

grid = [list(map(int, row.split())) for row in grid_text.strip().split('\n')]

# Try: if row has only 6s (no 1s), show all 6s; 
# if row has only 1s (no 6s), show all 1s;
# if row has both or neither, show all 8s
output_grid = []
for row in grid:
    non8_vals = [v for v in row if v != 8]
    if not non8_vals:
        output_grid.append([8] * len(row))  # empty row
    elif all(v == 6 for v in non8_vals):
        output_grid.append([6] * len(row))
    elif all(v == 1 for v in non8_vals):
        output_grid.append([1] * len(row))
    else:  # mixed or has both
        output_grid.append([8] * len(row))

print("6s-only→6s, 1s-only→1s, others→8s:")
print(json.dumps(output_grid[:20]))

